create table school_class (id bigint generated by default as identity primary key, owner varchar(255) not null, name varchar(100) not null, start_year integer not null, unique(owner,name,start_year));
create table student (id bigint generated by default as identity primary key, class_id bigint not null references school_class(id), name varchar(150) not null, student_number varchar(60) not null, joined_on date not null, unique(class_id,student_number));
create table course (id bigint generated by default as identity primary key, class_id bigint not null references school_class(id), subject varchar(100) not null, school_year integer not null, unique(class_id,subject,school_year));
create table schedule_slot (id bigint generated by default as identity primary key, course_id bigint not null references course(id), day_of_week integer not null, start_time time not null, end_time time not null, valid_from date not null, valid_until date not null);
create table lecture (id bigint generated by default as identity primary key, slot_id bigint not null references schedule_slot(id), lecture_date date not null, revision bigint not null default 0, unique(slot_id,lecture_date));
create table attendance (id bigint generated by default as identity primary key, lecture_id bigint not null references lecture(id), student_id bigint not null references student(id), present boolean not null, unique(lecture_id,student_id));
create index idx_class_owner on school_class(owner);
create index idx_student_class on student(class_id);
create index idx_course_class on course(class_id);
create index idx_slot_course on schedule_slot(course_id);
create index idx_attendance_student on attendance(student_id);
